var SHOPIFY_PRIMITIVE_CONTRACT_VERSION = 1;
var SHOPIFY_ICON_MATERIAL_VERSION = 2;
var shopifyThemeFileSchema = z16.object({
  path: z16.string().min(1),
  content: z16.string().min(1)
});
var primitiveFields = {
  tokensCss: z16.string().min(1),
  componentMaterialCss: z16.string(),
  coveredSourcePrimitives: z16.array(z16.string()),
  sourcePrimitivesWithShopifyAdapters: z16.array(z16.string()),
  themeFiles: z16.array(shopifyThemeFileSchema).min(1)
};
var iconLibrarySchema = z16.object({
  id: z16.string().min(1),
  name: z16.string().min(1),
  prefix: z16.string().min(1),
  variant: z16.string().min(1),
  provenance: z16.enum(["explicit", "iconify-source", "fallback"]),
  conflict: z16.object({ declared: z16.string(), detected: z16.string() }).optional()
});
var currentShopifyPrimitiveSetSchema = z16.object({
  ...primitiveFields,
  contractVersion: z16.literal(SHOPIFY_PRIMITIVE_CONTRACT_VERSION),
  iconMaterialVersion: z16.literal(SHOPIFY_ICON_MATERIAL_VERSION),
  iconLibrary: iconLibrarySchema
});
var shopifyPrimitiveSetSchema = z16.union([
  currentShopifyPrimitiveSetSchema,
  z16.object({ ...primitiveFields, contractVersion: z16.literal(1), iconMaterialVersion: z16.undefined().optional(), iconLibrary: z16.undefined().optional() })
]);
function parseShopifyPrimitiveSet(value) {
  const parsed = shopifyPrimitiveSetSchema.safeParse(value);
  return parsed.success ? parsed.data : null;
}

